import Link from "next/link";
import {
  ContactsTableExpandButton,
  ExpandableContactsTable,
} from "@/components/expandable-contacts-table";
import { ContactRow, type ContactListItem } from "./ContactRow";
import { ContactsEmptyState } from "./ContactsEmptyState";
import styles from "./contacts.module.css";

export function ContactList({
  contacts,
  total,
  page,
  query,
  hasContacts,
}: {
  contacts: ContactListItem[];
  total: number;
  page: number;
  query: string;
  hasContacts: boolean;
}) {
  const pages = Math.max(1, Math.ceil(total / 20));
  const href = (next: number) =>
    `/contacts?${new URLSearchParams({ q: query, page: String(next) })}`;
  return (
    <ExpandableContactsTable>
      {contacts.length ? (
        <ul aria-label="Your contacts" className="space-y-2.5">
          {contacts.map((contact, index) => (
            <ContactRow
              key={contact.id}
              contact={contact}
              expandControl={index === 0 ? <ContactsTableExpandButton /> : null}
            />
          ))}
        </ul>
      ) : (
        <ContactsEmptyState noMatches={!!query && hasContacts} />
      )}
      <nav
        aria-label="Pagination"
        className="mt-2 mb-7 flex flex-wrap items-center justify-between gap-3"
      >
        <p className="text-[13px] text-[var(--contacts-muted)]">
          Page {page} of {pages} · {total} {total === 1 ? "result" : "results"}
        </p>
        <div className="flex gap-2">
          {page > 1 && (
            <Link
              href={href(page - 1)}
              className={`${styles.secondary} secondary-button button-interaction inline-flex items-center justify-center min-h-11 py-2 px-4 [border:1px_solid_var(--contacts-strong)] rounded-full text-[13px] font-semibold text-[var(--contacts-purple)]`}
            >
              Previous
            </Link>
          )}
          {page < pages && (
            <Link
              href={href(page + 1)}
              className={`${styles.secondary} secondary-button button-interaction inline-flex items-center justify-center min-h-11 py-2 px-4 [border:1px_solid_var(--contacts-strong)] rounded-full text-[13px] font-semibold text-[var(--contacts-purple)]`}
            >
              Next
            </Link>
          )}
        </div>
      </nav>
    </ExpandableContactsTable>
  );
}
